using System.IO;
namespace MRS;
internal static class FileBandPlanTests
{
    internal static PacketObservation Observation(P25Identity id,P25BandPlan? band=null,P25Channel? channel=null)=>new(DateTimeOffset.UtcNow,"Synthetic control",false,774306250,null,"CRC valid","","","","Site status","synthetic",null,"","P25 Phase I",true,SourceKey:"test-epoch",P25BandPlan:band,P25Channel:channel,P25Identity:id);
    internal static void Run(Action<bool,string> check)
    {
        string root=Path.Combine(AppContext.BaseDirectory,"bandplan-tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);CsvBandPlans.Seed(root);var plans=new CsvBandPlans(root);plans.Reload();check(plans.Error==""&&plans.Plans.Count==7,"All packaged reference datasets round-trip through CSV");
        string custom=Path.Combine(root,"custom","channels.csv");PlanCsv.Write(custom,[new(){["downlink_mhz"]="851.187500",["uplink_mhz"]="806.187500",["lcn"]="00-0029",["label"]="Tower, \"north\"\nline two"}],["downlink_mhz","uplink_mhz","lcn","label"]);plans.Reload();var row=plans.Visible(851000000,852000000,new()).Single();check(row.Label=="Tower, \"north\"\nline two","CSV preserves quoted commas, quotes and multiline labels");check(!plans.Visible(806000000,807000000,new()).Any(),"Uplinks hidden by default");plans.Uplinks=true;check(plans.Visible(806000000,807000000,new()).Single().Uplink,"Uplink toggle exposes paired marker");plans.Hidden.Add("custom");check(!plans.Visible(851000000,852000000,new()).Any(),"Plan hide removes its overlay");
        var id=new P25Identity(0x345,0xBEE00,0x348,1,22);var provisional=new P25Identity(0x345,null,null,null,null);var collector=new P25BandCollector(root){Enabled=true};
        var band=new P25BandPlan(0,0,851006250,6250,-45000000,12500,1,null);var channel=new P25Channel(29,0,29,851187500,806187500,null,1,"resolved");
        collector.Observe(Observation(provisional,band));collector.Observe(Observation(id,channel:channel));collector.Flush(true);
        string site=Path.Combine(root,"p25","BEE00-348","site-001-022");check(File.Exists(Path.Combine(site,"spacing.csv"))&&File.Exists(Path.Combine(site,"channels.csv")),"Pending definition attaches only after full serving-site identity");
        var rows=PlanCsv.Read(Path.Combine(site,"channels.csv"));rows[0]["label"]="My site label";PlanCsv.Write(Path.Combine(site,"channels.csv"),rows,rows[0].Keys.ToArray());collector.Observe(Observation(id,channel:channel));collector.Flush(true);rows=PlanCsv.Read(Path.Combine(site,"channels.csv"));check(rows.Count==1&&rows[0]["label"]=="My site label"&&rows[0]["lcn"]=="00-0029","Repeated grants preserve leading zeros, user label and single row");
        collector.Observe(Observation(id,channel:channel) with{Replay=true,P25Identity=id with{SiteId=99}});collector.Observe(Observation(id,channel:channel) with{Validated=false,P25Identity=id with{SiteId=98}});collector.Flush(true);check(!Directory.Exists(Path.Combine(root,"p25","BEE00-348","site-001-099"))&&!Directory.Exists(Path.Combine(root,"p25","BEE00-348","site-001-098")),"Replay and invalid frames cannot populate live site files");
        collector.Observe(Observation(id) with{P25SiteAnnouncement=new(0x348,1,23,null,null,[new(channel,0)])});collector.Flush(true);check(File.Exists(Path.Combine(root,"p25","BEE00-348","site-001-023","channels.csv")),"Neighbor announcement belongs to advertised site");
        collector.Observe(Observation(id,channel:channel with{DownlinkHz=851200000}));collector.Flush(true);rows=PlanCsv.Read(Path.Combine(site,"channels.csv"));check(rows.Count==2&&rows.All(r=>r["conflict"].Contains("review")),"Conflicting LCN definitions retained and flagged");
        string original="lcn,downlink_mhz\n00-0029,bad";File.WriteAllText(Path.Combine(site,"channels.csv"),original);collector.Observe(Observation(id,channel:channel));collector.Flush(true);check(File.ReadAllText(Path.Combine(site,"channels.csv"))==original&&collector.Error!="","Malformed edited file is never overwritten by collector");plans.Reload();check(plans.Error.Contains("channels.csv"),"Invalid CSV has visible validation error");
        string clean=Path.Combine(root,"epoch");var epochs=new P25BandCollector(clean){Enabled=true};epochs.Observe(Observation(provisional,band));epochs.Reset();epochs.Observe(Observation(id,channel:channel));epochs.Flush(true);check(!File.Exists(Path.Combine(clean,"p25","BEE00-348","site-001-022","spacing.csv"))&&epochs.PendingCount==1,"Unidentified observations never cross a receiver epoch");
        string late=Path.Combine(root,"late");var lateCollector=new P25BandCollector(late){Enabled=true};lateCollector.Observe(Observation(id,channel:channel with{DownlinkHz=null,UplinkHz=null}));lateCollector.Observe(Observation(id,band));lateCollector.Flush(true);check(PlanCsv.Hz(PlanCsv.Read(Path.Combine(late,"p25","BEE00-348","site-001-022","channels.csv"))[0],"downlink")==851187500,"Late identifier definition resolves a pending channel within its original context");
        string changed=Path.Combine(root,"changed");var changeCollector=new P25BandCollector(changed){Enabled=true};changeCollector.Observe(Observation(id,band));changeCollector.Observe(Observation(id with{SiteId=24},channel:channel with{DownlinkHz=null,UplinkHz=null}));changeCollector.Flush(true);check(!File.Exists(Path.Combine(changed,"p25","BEE00-348","site-001-024","channels.csv")),"Changed site identity cannot reuse prior site's cached definition");
        plans.Grid=true;plans.Reload();check(plans.Visible(851000000,851300000,new()).Any(m=>m.Grid),"Calculated grid is separately marked as not observed");
    }
}
